def _validate():
    """
    Dev-time sanity check: every non-English language should cover
    every English key. Missing keys silently fall back to English at
    runtime (see t() below) rather than crashing the app, but this
    surfaces gaps immediately via py_compile/import rather than a user
    stumbling on a mixed-language page later. Runs once at import.
    """
    base_keys = set(_EN.keys())
    for lang, table in TRANSLATIONS.items():
        if lang == "en":
            continue
        missing = base_keys - set(table.keys())
        if missing:
            import warnings
            warnings.warn(
                f"saas_i18n: language '{lang}' is missing {len(missing)} "
                f"key(s) vs English: {sorted(missing)[:5]}..."
                if len(missing) > 5 else
                f"saas_i18n: language '{lang}' is missing key(s) vs "
                f"English: {sorted(missing)}"
            )


_validate()


def t(key, lang=DEFAULT_LANGUAGE, **kwargs):
    """
    Looks up `key` in the given language, falling back to English (and
    finally to the raw key itself) if missing, then applies **kwargs
    via str.format() for any templated {placeholders}. A malformed/
    missing format argument returns the unformatted template rather
    than raising, so a translation typo degrades to "slightly wrong
    text" instead of a crashed page.
    """
    lang_table = TRANSLATIONS.get(lang) or _EN
    text = lang_table.get(key)
    if text is None:
        text = _EN.get(key, key)
    if kwargs:
        try:
            return text.format(**kwargs)
        except (KeyError, IndexError, ValueError):
            return text
    return text
